import { Fragment, FunctionalComponent } from 'preact';
import PropTypes from 'prop-types';
import { useState, useRef } from 'preact/hooks';
import { useDispatch } from 'react-redux';

import { getTranslation } from '../../../../../../shared/chromeApi';
import { clickedSupportUs } from '../../../../ui/slice';

import styles from './styles.module.scss';
import { MODALS } from '../../../../../../shared/utils/dict';

import LIST from './list.json';

const AppItem = ({ item }) => (
  <li>
    <a href={item.url}>
      <img src={`img/services/${item.img}`} width="60" height="60" alt="" />
      <span>{getTranslation(`apps_app_${item.name}`)}</span>
    </a>
  </li>
);

AppItem.propTypes = {
  item: PropTypes.object.isRequired,
};

// -----------------------------------------------------------------------------

interface Props {
  onClose: () => void;
}

const Apps: FunctionalComponent<Props> = ({ onClose }: Props) => {
  const dispatch = useDispatch();

  const [isScrollable, setScrollable] = useState(false);
  const $appsPopupRef = useRef<HTMLElement>();

  const handleShowMore = () => {
    setScrollable(true);
    $appsPopupRef.current.scrollTo(0, $appsPopupRef.current.scrollHeight);
  };

  const handleScroll = (evt) => {
    const { scrollTop } = evt.currentTarget;
    setScrollable(!!scrollTop);
  };

  const handleSupportUs = () => {
    dispatch(clickedSupportUs(MODALS.Patreon));
    onClose();
  };

  return (
    <Fragment>
      <div className={styles.overlay} onClick={onClose} />
      <section className={styles.appsPopup}>
        <section
          className={`${styles.appsScrollable} ${isScrollable ? '' : styles.topPosition
            }`}
          ref={$appsPopupRef}
          onScroll={handleScroll}
        >
          <div className={styles.appsContent}>
            <ul className={`${styles.appsList} ${styles.appsListPrimary}`}>
              {LIST.slice(0, 12).map((item) => (
                <AppItem item={item} key={item.name} />
              ))}
            </ul>
          </div>
          <span className={styles.separator} />

          {/* {!isScrollable && (
            <button className={styles.moreAppsBtn} onClick={handleShowMore}>
              {getTranslation('apps_show_more')}
            </button>
          )} */}

          <div className={styles.appsContent}>
            <ul className={`${styles.appsList} ${styles.appsListSecondary}`}>
              {LIST.slice(12).map((item) => (
                <AppItem item={item} key={item.name} />
              ))}
            </ul>
          </div>
        </section>
        <section className={styles.appsLinks}>
          <div>
            <a
              href="https://about.oceanhero.today/how-it-works"
            // onClick={trackHowItWorksClick}
            >
              {getTranslation('new_tab_header_how')}
            </a>
          </div>
          <div>
            <a href="https://about.oceanhero.today/about-us">
              {getTranslation('new_tab_header_about')}
            </a>
          </div>
          <div>
            <a href="https://about.oceanhero.today/our-mission">
              {getTranslation('new_tab_header_mission')}
            </a>
          </div>
          <div>
            <a href="https://oceanhero.zendesk.com/hc/en-us">
              {getTranslation('new_tab_header_faq')}
            </a>
          </div>
          <div>
            <a href="https://marine-life.oceanhero.today">Encyclopedia</a>
          </div>
          <div>
            <a className={styles.supportUs} onClick={handleSupportUs}>
              {getTranslation('new_tab_header_support_us')}
            </a>
          </div>
        </section>
      </section>
    </Fragment>
  );
};

export default Apps;
